<?php

namespace App\Extensions\Ai\Http\Controllers;

use App\Extensions\Ai\Services\AiAssistant;
use App\Extensions\Ai\Services\AiConversationService;
use App\Http\Controllers\Controller;
use App\Models\Page;
use App\Models\Space;
use App\Models\User;
use App\Services\Knowledgebase\PageAcl;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\Request;
use Throwable;

/**
 * "Ask the knowledge base" assistant. Answers are generated by a local Ollama
 * model over content the user is allowed to see.
 */
class AssistantController extends Controller
{
    public function __construct(
        private readonly AiAssistant $assistant,
        private readonly AiConversationService $conversations,
    ) {
    }

    public function status(Request $request): JsonResponse
    {
        $user = $request->user();

        return response()->json([
            'data' => [
                'enabled' => $this->assistant->enabled() && $this->assistant->canUse($user),
                'model' => $this->assistant->model(),
                'sections' => $this->assistant->sections(),
                'show_sources' => $this->assistant->showSources(),
            ],
        ]);
    }

    public function ask(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return response()->json([
                'message' => 'AI-ассистент не настроен (включите его в админке: «ИИ-ассистент»).',
            ], 503);
        }

        if ($forbidden = $this->forbidden($request->user())) {
            return $forbidden;
        }

        $validated = $request->validate([
            'question' => 'required|string|min:2|max:2000',
            'types' => 'sometimes|array',
            'types.*' => 'in:' . implode(',', AiAssistant::ALLOWED_TYPES),
            'conversation_id' => 'nullable|integer|min:1',
        ]);

        $user = $request->user();

        // A foreign conversation must look missing, not forbidden.
        $conversation = isset($validated['conversation_id'])
            ? $this->conversations->find($user, (int) $validated['conversation_id'])
            : $this->conversations->start($user);

        // Read the history before the new question is written, so it is not replayed twice.
        $history = $this->conversations->history($conversation, $this->assistant->historyWindow());
        $startedAt = microtime(true);

        try {
            $result = $this->assistant->ask($user, $validated['question'], $validated['types'] ?? [], $history);
        } catch (Throwable $e) {
            $this->conversations->recordFailure($conversation, $validated['question'], $e->getMessage());

            return response()->json([
                'message' => 'Не удалось получить ответ: ' . $e->getMessage(),
            ], 503);
        }

        $this->conversations->record(
            $conversation,
            $validated['question'],
            $result,
            (int) round((microtime(true) - $startedAt) * 1000),
        );

        return response()->json(['data' => $result + [
            'conversation_id' => (int) $conversation->id,
            'conversation_title' => $conversation->title,
        ]]);
    }

    /** Summarize a knowledgebase page (ACL-checked). */
    public function summarize(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return $this->disabled();
        }

        if ($forbidden = $this->forbidden($request->user())) {
            return $forbidden;
        }

        $validated = $request->validate([
            'page_id' => 'required|integer|exists:pages,id',
        ]);

        $page = Page::findOrFail((int) $validated['page_id']);
        $space = Space::find($page->space_id);
        $user = $request->user();

        if ($space === null
            || ! Space::whereKey($space->id)->visibleTo($user)->exists()
            || ! PageAcl::for($space, $user)->canView($page)) {
            abort(404, 'Страница не найдена');
        }

        try {
            $summary = $this->assistant->summarize((string) $page->title, Page::plainText((string) $page->body));
        } catch (Throwable $e) {
            return response()->json(['message' => 'Не удалось получить резюме: ' . $e->getMessage()], 503);
        }

        return response()->json([
            'data' => [
                'page_id' => (int) $page->id,
                'summary' => $summary,
                'model' => $this->assistant->model(),
            ],
        ]);
    }

    /** Generate a task or email draft from a short prompt. */
    public function draft(Request $request): JsonResponse
    {
        if (! $this->assistant->enabled()) {
            return $this->disabled();
        }

        if ($forbidden = $this->forbidden($request->user())) {
            return $forbidden;
        }

        $validated = $request->validate([
            'kind' => 'required|in:task,mail',
            'prompt' => 'required|string|min:3|max:2000',
        ]);

        try {
            $text = $this->assistant->draft($validated['kind'], $validated['prompt']);
        } catch (Throwable $e) {
            return response()->json(['message' => 'Не удалось сгенерировать черновик: ' . $e->getMessage()], 503);
        }

        return response()->json([
            'data' => [
                'kind' => $validated['kind'],
                'draft' => $text,
                'model' => $this->assistant->model(),
            ],
        ]);
    }

    /** The assistant is off for this role when an administrator limited it. */
    private function forbidden(?User $user): ?JsonResponse
    {
        if ($user === null || $this->assistant->canUse($user)) {
            return null;
        }

        return response()->json([
            'message' => 'ИИ-ассистент недоступен для вашей роли.',
        ], 403);
    }

    private function disabled(): JsonResponse
    {
        return response()->json([
            'message' => 'AI-ассистент не настроен (включите его в админке: «ИИ-ассистент»).',
        ], 503);
    }
}
